// REST: text JSON over HTTP/1.1
@RestController
@RequestMapping("/api/inventory")
public class InventoryController {

    private final InventoryService service;

    public InventoryController(InventoryService service) {
        this.service = service;
    }

    @GetMapping("/{sku}")
    public ResponseEntity<StockResponse> getStock(@PathVariable String sku) {
        return ResponseEntity.ok(new StockResponse(sku, service.countFor(sku)));
    }
}

record StockResponse(String sku, int available) {}

// gRPC defines the same call in a .proto file and generates a typed stub:
//   service Inventory { rpc GetStock(StockRequest) returns (StockResponse); }
// then: StockResponse r = inventoryStub.getStock(request);  // binary, HTTP/2
