// REST: resource (noun) + HTTP verb
@RestController
@RequestMapping("/api/orders")
public class OrderRestController {

    private final OrderService service;

    public OrderRestController(OrderService service) {
        this.service = service;
    }

    // PATCH /api/orders/42  body: {"status":"CANCELLED"}  - RESTful state change
    @PatchMapping("/{id}")
    public ResponseEntity<Order> updateStatus(@PathVariable Long id,
                                              @RequestBody StatusUpdate body) {
        return ResponseEntity.ok(service.changeStatus(id, body.status()));
    }
}

record StatusUpdate(String status) {}

// RPC style names the action in the path instead:
//   POST /cancelOrder   body: {"orderId":42}
// Both run over HTTP, but REST leans on verbs+nouns; RPC leans on function calls.
```

