// REST is the default; switch technology per access pattern.
@RestController
@RequestMapping("/api/feed")
public class FeedController {

    private final FeedService service;

    public FeedController(FeedService service) {
        this.service = service;
    }

    // REST: standard request/response for normal reads (the default choice)
    @GetMapping("/{userId}")
    public ResponseEntity<List<Post>> getFeed(@PathVariable Long userId) {
        return ResponseEntity.ok(service.feedFor(userId));
    }
}

// Real-time push (chat, live scores) -> WebSocket instead of REST polling:
@Controller
class ChatController {
    @MessageMapping("/send")            // STOMP over WebSocket
    @SendTo("/topic/messages")
    public ChatMessage handle(ChatMessage msg) {
        return msg;                     // pushed to every subscriber
    }
}
// Internal high-throughput calls -> gRPC; flexible client shapes -> GraphQL.
